message.content:
{
  "description": "The creature is a large quadrupedal mammal shown in right-facing profile against a plain off-white background. Its body, head, and limbs are covered in dense, shaggy brown fur that is darker on the lower legs and lighter tan around the muzzle and cheeks, giving the overall appearance of a bear. Fused to its dorsal side from just behind the neck to the rump is a large, glossy, hard, dark reddish-brown segmented carapace resembling a beetle's exoskeleton, with a smooth domed shield over the shoulders and overlapping ridged segments behind it. A single large, glossy blackish-brown curved horn with notches along its inner edge rises from the center of the forehead and arches upward and backward. The animal stands on four thick legs with clawed paws, and a very short furry tail is visible at the rear beneath the carapace.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like, broad with dense brown fur, lighter tan fur around the muzzle and lower cheek, a large black nose at the tip of the snout, small brown eyes in profile, and a closed mouth",
      "where": "at the front of the body, facing to the right"
    },
    {
      "part": "horns",
      "looks_like": "single large glossy dark brown to black beetle-like horn, curved like a sickle with a forked tip and several tooth-like notches along the inner concave edge, smooth and shiny",
      "where": "emerging from the midline of the forehead between the ears, arching up and backward over the head"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears covered in thick brown fur, with slightly darker edges",
      "where": "on top of the head, one on each side of the horn base, the right ear more visible in profile"
    },
    {
      "part": "legs",
      "looks_like": "four thick, sturdy, heavily furred legs with long shaggy brown fur, two forelegs and two hindlegs, muscular in appearance",
      "where": "supporting the body from below, forelegs under the chest and hindlegs under the hips"
    },
    {
      "part": "feet",
      "looks_like": "four broad paws with dark, long, curved claws protruding from the fur, five claws visible on each front paw and on the visible hind paws",
      "where": "at the bottom ends of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "very short, stubby, furry brown tail, barely protruding from the fur",
      "where": "at the rear of the body on the left side, just below the posterior edge of the carapace"
    },
    {
      "part": "shell",
      "looks_like": "large hard glossy carapace, dark reddish-brown with blackish edges and a shiny surface, domed over the back",
      "where": "covering the entire dorsal surface from the back of the neck to above the tail"
    },
    {
      "part": "plates",
      "looks_like": "overlapping transverse plates forming the shell: a large smooth shoulder shield with fine horizontal striations and a black rim at the front, followed by about ten narrower ridged segments toward the rear, with small side flaps along the lower edge each bearing two small circular holes",
      "where": "composing the shell on the back, with the large shield over the shoulders and the segmented plates extending rearward over the torso and hips"
    },
    {
      "part": "markings",
      "looks_like": "a row of seven oval dark-rimmed openings resembling spiracles, with light centers, set in the fur",
      "where": "in a horizontal line on the side of the torso in the brown fur just below the lower edge of the shell, between the fore and hind legs"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
